class LRUCache:
    def __init__(self, capacity: int):
        self.capacity = capacity
        self.cache = {}  # Dictionary to store items and their values
        self.lru = []  # List to hold items in reverse order of least recently used

    def get(self, key: int) -> int:
        if key in self.cache:
            self.lru.remove(key)
            self.lru.append(key)
            return self.cache[key]
        return -1

    def put(self, key: int, value: int) -> None:
        if key in self.cache:
            self.lru.remove(key)
        self.lru.append(key)
        self.cache[key] = value
        if len(self.cache) > self.capacity:
            self.lru.remove(self.lru[0])  # Evict the least recently used item
            self.cache.pop(self.lru[0])  # Remove the item from the cache
